@import "@fontsource-variable/ibm-plex-sans";
@import "@fontsource-variable/newsreader/opsz.css";

/* Light (faithful): white page, soft lemon (highlight) and ice-blue (accent) washes,
   blue-tinted charcoal text, one cyan-blue brand colour, a deep navy closing strip (secondary). */
:root {
  --background: oklch(1 0 0);
  --foreground: oklch(0.288 0.009 220);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.288 0.009 220);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.288 0.009 220);
  --primary: oklch(0.649 0.125 227);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.228 0.043 228);
  --secondary-foreground: oklch(1 0 0);
  --muted: oklch(0.942 0.007 209);
  --muted-foreground: oklch(0.499 0.039 213);
  --accent: oklch(0.948 0.022 214);
  --accent-foreground: oklch(0.288 0.009 220);
  --destructive: oklch(0.645 0.207 31.5);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.865 0.021 224);
  --input: oklch(0.865 0.021 224);
  --ring: oklch(0.649 0.125 227);
  --highlight: oklch(0.958 0.116 103);
  --highlight-foreground: oklch(0.288 0.009 220);
  --glow: oklch(0.827 0.082 217);
  --chart-1: oklch(0.649 0.125 227);
  --chart-2: oklch(0.76 0.176 61);
  --chart-3: oklch(0.702 0.187 29);
  --chart-4: oklch(0.657 0.221 143);
  --chart-5: oklch(0.373 0.07 224);
  --sidebar: oklch(0.965 0.003 197);
  --sidebar-foreground: oklch(0.288 0.009 220);
  --sidebar-primary: oklch(0.649 0.125 227);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.948 0.022 214);
  --sidebar-accent-foreground: oklch(0.288 0.009 220);
  --sidebar-border: oklch(0.865 0.021 224);
  --sidebar-ring: oklch(0.649 0.125 227);

  --typeface-body: "IBM Plex Sans Variable", "IBM Plex Sans", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Newsreader Variable", "Newsreader", Georgia, serif;
  --typeface-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.75rem;
  --page-width: 90rem;
  --page-gutter: clamp(1.25rem, 2.78vw, 2.5rem);
  --section-y: clamp(6.25rem, 13.9vw, 12.5rem);
}

/* Dark: a night version in the same spirit: navy page and cards, the lemon wash dimmed to
   olive, the ice blue to a deep teal, the brand blue brightened. */
.dark {
  --background: oklch(0.2 0.03 228);
  --foreground: oklch(0.96 0.005 210);
  --card: oklch(0.25 0.035 228);
  --card-foreground: oklch(0.96 0.005 210);
  --popover: oklch(0.25 0.035 228);
  --popover-foreground: oklch(0.96 0.005 210);
  --primary: oklch(0.72 0.13 225);
  --primary-foreground: oklch(0.18 0.03 228);
  --secondary: oklch(0.14 0.03 228);
  --secondary-foreground: oklch(0.96 0.005 210);
  --muted: oklch(0.3 0.03 225);
  --muted-foreground: oklch(0.76 0.03 215);
  --accent: oklch(0.27 0.045 222);
  --accent-foreground: oklch(0.96 0.005 210);
  --destructive: oklch(0.7 0.19 29);
  --destructive-foreground: oklch(0.18 0.03 228);
  --border: oklch(1 0 0 / 14%);
  --input: oklch(1 0 0 / 18%);
  --ring: oklch(0.72 0.13 225);
  --highlight: oklch(0.34 0.06 103);
  --highlight-foreground: oklch(0.96 0.005 210);
  --glow: oklch(0.6 0.1 220);
  --chart-1: oklch(0.72 0.13 225);
  --chart-2: oklch(0.8 0.15 70);
  --chart-3: oklch(0.72 0.17 29);
  --chart-4: oklch(0.72 0.18 143);
  --chart-5: oklch(0.82 0.08 217);
  --sidebar: oklch(0.25 0.035 228);
  --sidebar-foreground: oklch(0.96 0.005 210);
  --sidebar-primary: oklch(0.72 0.13 225);
  --sidebar-primary-foreground: oklch(0.18 0.03 228);
  --sidebar-accent: oklch(0.3 0.03 225);
  --sidebar-accent-foreground: oklch(0.96 0.005 210);
  --sidebar-border: oklch(1 0 0 / 14%);
  --sidebar-ring: oklch(0.72 0.13 225);
}
